 $('erpRuleTemplate').onclick=()=>safe(async()=>{const defs=[{code:'retention_insurance',name_ar:'تأمين محتجز',calculation_type:'Percent',rate:2,sort_order:10},{code:'final_retention',name_ar:'تأمين نهائي',calculation_type:'Percent',rate:2,sort_order:20},{code:'social_insurance',name_ar:'تأمينات اجتماعية',calculation_type:'Percent',rate:1,sort_order:30},{code:'informal_labor',name_ar:'عمالة غير منتظمة',calculation_type:'Percent',rate:0.6,sort_order:40},{code:'profit_tax',name_ar:'ضريبة أرباح',calculation_type:'Percent',rate:1,sort_order:50},{code:'stamp_duty',name_ar:'دمغة',calculation_type:'Fixed',rate:0,sort_order:60},{code:'advance_payment',name_ar:'تسوية دفعات مقدمة',calculation_type:'Fixed',rate:0,sort_order:70},{code:'works_guarantee',name_ar:'حجز ضمان الأعمال',calculation_type:'Percent',rate:0,sort_order:80},{code:'store_withdrawals',name_ar:'مسحوبات المخازن وخامات الموقع',calculation_type:'Fixed',rate:0,sort_order:90}];let added=0;for(const side of ['Customer','Subcontractor']){const existing=(await api(`/api/contracts-erp/${id}/deduction-rules?settlement_side=${side}`)).items||[];const codes=new Set(existing.map(x=>x.code));for(const d of defs.filter(x=>!codes.has(x.code))){await api(`/api/contracts-erp/${id}/deduction-rules`,{method:'POST',json:{...d,settlement_side:side,base_type:'CurrentWork',posting_side:side==='Customer'?'Debit':'Credit',gl_account_id:null,cap_amount:null,is_active:true}});added++;}}if(!added){toast('البنود القياسية موجودة بالفعل');}else{const r=await api(`/api/contracts-erp/${id}/deduction-rules/auto-link`,{method:'POST',json:{}});toast(`تمت إضافة ${added} بند، وربط ${r.linked.length} بحساب من الشجرة${r.missing.length?` — ${r.missing.length} بند يحتاج ربطًا يدويًا`:''}`);}await erpLoad();})();
 $('erpRuleAutoLink').onclick=()=>safe(async()=>{const r=await api(`/api/contracts-erp/${id}/deduction-rules/auto-link`,{method:'POST',json:{}});const lines=[...r.linked.map(x=>`✔ ${x.name} ← ${x.account}`),...r.missing.map(x=>`✘ ${x.name}: لم يوجد حساب مناسب، اربطه يدويًا (تعديل)`)];toast(lines.length?lines.join(' | '):'كل البنود مربوطة بحسابات بالفعل');await erpLoad();})();
 $('erpConfig').onclick=()=>safe(async()=>{const [data,acc]=await Promise.all([api(`/api/contracts-erp/${id}/accounting-config`),api('/accounts?is_active=true&limit=1000')]);const opts=(acc.items||[]).map(a=>[String(a.account_id),`${a.account_code} — ${a.account_name_ar}`]);const acct=(name,label,req)=>({name,label,type:'select',options:opts,searchable:true,optional:!req,required:!!req});const cfg=data.items?.[0]||{};formDialog({title:'إعدادات المحاسبة والضريبة للعقد',fields:[{name:'settlement_side',label:'نوع المستخلص',type:'select',options:[['Customer','مستخلص عميل'],['Subcontractor','مستخلص مقاول باطن']],required:true},{name:'company_id',label:'رقم الشركة',type:'number',required:true},{name:'fiscal_year_id',label:'رقم السنة المالية',type:'number',required:true},acct('control_account_id','حساب العميل / المقاول (من الشجرة)',true),acct('work_account_id','حساب الإيراد / تكلفة الأعمال (من الشجرة)',true),acct('retention_account_id','حساب المحتجز / الضمان (افتراضي لبنود التأمين)'),acct('advance_account_id','حساب الدفعات المقدمة'),acct('tax_account_id','حساب الضرائب والتأمينات (افتراضي للبنود غير المربوطة)'),acct('vat_account_id','حساب ضريبة القيمة المضافة'),{name:'default_vat_rate',label:'نسبة القيمة المضافة الافتراضية % (قابلة للتعديل لكل مستخلص)',type:'number',step:'0.0001',required:true}],values:{default_vat_rate:'0',...cfg,settlement_side:cfg.settlement_side||'Customer'},onSubmit:async v=>{for(const k of ['company_id','fiscal_year_id','control_account_id','work_account_id','retention_account_id','advance_account_id','tax_account_id','vat_account_id'])v[k]=v[k]?Number(v[k]):null;v.default_vat_rate=Number(v.default_vat_rate||0);await api(`/api/contracts-erp/${id}/accounting-config`,{method:'PUT',json:v});toast('تم حفظ إعدادات المحاسبة');await erpLoad();}});})();
 const addSettlement=async side=>{const [summary,ruleData,accountData]=await Promise.all([api(`/api/contracts-erp/${id}/settlement-summary?settlement_side=${side}`),api(`/api/contracts-erp/${id}/deduction-rules?settlement_side=${side}`),api('/accounts?is_active=true&limit=1000')]);const technical=summary.items||[];const rules=(ruleData.items||[]).filter(r=>r.is_active);const accountById=new Map((accountData.items||[]).map(a=>[String(a.account_id),`${a.account_code} — ${a.account_name_ar}`]));const fixedRules=rules.filter(r=>r.calculation_type==='Fixed');const fields=[{name:'settlement_no',label:'رقم المستخلص',required:true},{name:'settlement_date',label:'التاريخ',type:'date',required:true},{name:'counterparty_name',label:'اسم العميل / المقاول',required:true}];if(technical.length){fields.push({name:'account_filter',label:'فلتر حسابات البنود من الشجرة',type:'select',optional:true,searchable:true,options:[...new Set(technical.map(i=>String(i.account_id||'')))].filter(Boolean).map(a=>[a,accountById.get(a)||`حساب ${a}`])});for(const item of technical){fields.push({name:`qty_${item.item_id}`,label:`${item.item_no} — ${item.description} (متبقي ${item.remaining_quantity} ${item.unit}، سعر ${item.unit_price})`,type:'number',step:'0.0001',min:0});}fields.push({name:'live_work_total',label:'إجمالي قيمة الأعمال الحالية — محسوب تلقائيًا',readonly:true,full:true});}else{fields.push({name:'work_value',label:'قيمة أعمال الفترة الحالية',type:'number',step:'0.01',min:0.01,required:true});}for(const r of fixedRules)fields.push({name:`deduction_${r.code}`,label:`${r.name_ar} — مبلغ هذا المستخلص (مبلغ ثابت)`,type:'number',step:'0.01',min:0});fields.push({name:'vat_rate',label:'نسبة الضريبة % (اتركها 0 إن لم تطبق)',type:'number',step:'0.0001'},{name:'notes',label:'ملاحظات',type:'textarea',rows:6,minHeight:130,full:true});const values={settlement_date:today(),vat_rate:'0',live_work_total:'0.00'};if(!technical.length)values.work_value='0';for(const item of technical)values[`qty_${item.item_id}`]='0';formDialog({title:side==='Customer'?'مستخلص عميل — تحديد كميات البنود':'مستخلص مقاول باطن — تحديد كميات البنود',fields,values,onOpen:(dlg,form)=>{const filter=form.elements.account_filter;const updateTotal=()=>{const total=technical.reduce((sum,item)=>{const quantity=Number(form.elements[`qty_${item.item_id}`]?.value||0);const line=Math.round((quantity*Number(item.unit_price||0)+Number.EPSILON)*100)/100;return sum+line;},0);if(form.elements.live_work_total)form.elements.live_work_total.value=money(total);};for(const item of technical){form.elements[`qty_${item.item_id}`]?.addEventListener('input',updateTotal);}updateTotal();if(!filter)return;const apply=()=>{for(const item of technical){const input=form.elements[`qty_${item.item_id}`];if(input)input.closest('.f').hidden=!!(filter.value&&String(item.account_id||'')!==filter.value);}};filter.onchange=apply;},onSubmit:async v=>{const items=technical.map(item=>({contract_item_id:item.item_id,quantity:Number(v[`qty_${item.item_id}`]||0)})).filter(x=>x.quantity>0);if(technical.length&&!items.length){toast('أدخل كمية واحدة على الأقل في بنود المستخلص');return;}const deduction_overrides={};for(const r of fixedRules){const raw=v[`deduction_${r.code}`];if(raw!==undefined&&raw!=='')deduction_overrides[r.code]=Number(raw||0);}const payload={settlement_side:side,settlement_no:v.settlement_no,settlement_date:v.settlement_date,counterparty_name:v.counterparty_name,vat_rate:Number(v.vat_rate||0),notes:v.notes||null,deduction_overrides};if(technical.length)payload.items=items;else payload.work_value=Number(v.work_value||0);const created=await api(`/api/contracts-erp/${id}/settlements`,{method:'POST',json:payload});toast(`تم حفظ المستخلص وإرساله للاعتماد المالي — الأعمال ${money(created.work_value)}، الضريبة ${money(created.vat_amount)}، الصافي ${money(created.net_amount)}`);await erpLoad();}});};
